const fs=require('fs'),path=require('path');let timer,running=false,opened=false,created=false;
exports.load=()=>{const project=Editor.Project.path;timer=setInterval(async()=>{if(running)return;running=true;try{if(!opened){if(!created){await Editor.Message.request('scene','execute-scene-script',{name:'p3-probe',method:'createFixture',args:[project]});created=true;fs.writeFileSync(path.join(project,'qualification-created.json'),'{}');}await Editor.Message.request('asset-db','refresh-asset','db://assets/Qualification.scene');const id=await Editor.Message.request('asset-db','query-uuid','db://assets/Qualification.scene');if(!id)throw Error('Asset not ready');const ready=await Editor.Message.request('scene','query-is-ready');if(!ready)throw Error('Scene not ready');const openedResult=await Editor.Message.request('scene','open-scene',id);const current=await Editor.Message.request('scene','query-current-scene');if(!openedResult&&current!==id)throw Error('Scene open not completed');console.info('[p3-qualification] opened '+JSON.stringify({id,current,url:await Editor.Message.request('asset-db','query-url',current)}));opened=true;}const stageCommand=path.join(project,'qualification-stage.json');if(fs.existsSync(stageCommand)){fs.unlinkSync(stageCommand);await Editor.Message.request('scene','snapshot-abort');const uuid=await Editor.Message.request('asset-db','query-uuid','db://assets/Qualification.prefab');await Editor.Message.request('asset-db','open-asset',uuid);console.info('[p3-qualification] opened prefab '+uuid);}const command=path.join(project,'qualification-command.json');if(fs.existsSync(command)){fs.unlinkSync(command);const tree=await Editor.Message.request('scene','query-node-tree');const panel=tree.children.find(n=>n.name==='Panel');if(!panel)throw Error('Panel missing');const before=await Editor.Message.request('scene','query-node',panel.uuid);await Editor.Message.request('scene','set-property',{uuid:panel.uuid,path:'position',dump:{type:'cc.Vec3',value:{x:99,y:0,z:0}},record:true});await Editor.Message.request('scene','snapshot');await new Promise(resolve=>setTimeout(resolve,100));const after=await Editor.Message.request('scene','query-node',panel.uuid);const dirty=await Editor.Message.request('scene','query-dirty');const count=n=>1+(n.children||[]).reduce((sum,n)=>sum+count(n),0);fs.writeFileSync(path.join(project,'qualification-result.json'),JSON.stringify({status:'PASS',before,after,dirty,nodeCount:count(tree),tree},null,2));}}catch(e){console.warn('[p3-qualification] '+String(e.stack||e));}finally{running=false;}},1500);};exports.unload=()=>clearInterval(timer);
